type IconName = "chevron" | "check" | "alert" | "merge" | "plus" | "folder" | "laptop" | "cloud" | "mic" | "arrow" | "signal" | "github";
function Icon({ name, size = 16 }: { name: IconName; size?: number }) {
  const paths: Record<IconName, ReactNode> = {
    chevron: <path d="m6 4 4 4-4 4" />,
    check: <path d="m3.5 8 3 3 6-6" />,
    alert: <><path d="M7.1 2.8a1 1 0 0 1 1.8 0l5.4 10a.8.8 0 0 1-.7 1.2H2.4a.8.8 0 0 1-.7-1.2Z" /><path d="M8 6v3m0 2.3v.2" /></>,
    merge: <><circle cx="4" cy="3" r="1.5" /><circle cx="4" cy="13" r="1.5" /><circle cx="12" cy="9" r="1.5" /><path d="M4 4.5v7M5.5 3c5 0 1 6 5 6" /></>,
    plus: <path d="M8 2.5v11M2.5 8h11" />,
    folder: <path d="M2 5V3.5h4L8 5h6v2M2 6.5h12l-1.2 6h-12Z" />,
    laptop: <><path d="M3 3h10v8H3zM1 13h14" /></>,
    cloud: <path d="M4 12h7a3 3 0 1 0-.6-5.9 3.5 3.5 0 0 0-6.8-.6A3.3 3.3 0 0 0 4 12Z" />,
    mic: <><rect x="6" y="2" width="4" height="8" rx="2" /><path d="M4 7a4 4 0 0 0 8 0M8 11v3m-2 0h4" /></>,
    arrow: <path d="M8 13V2M3 7l5-5 5 5" />,
    signal: <path d="M2 13v-2m3 2V8m3 5V6m3 7V3m3 10V1" />,
    github: <><path fill="currentColor" stroke="none" d="M8 1a7 7 0 0 0-2.2 13.6v-1.5c-1.8.4-2.2-.8-2.2-.8-.3-.7-.7-.9-.7-.9-.6-.4 0-.4 0-.4.7 0 1 .7 1 .7.6 1 1.5.7 1.9.5.1-.4.3-.7.5-.8-1.4-.2-2.9-.7-2.9-3.1 0-.7.2-1.2.7-1.7-.1-.2-.3-.8.1-1.7 0 0 .6-.2 1.9.7a6.5 6.5 0 0 1 3.8 0c1.3-.9 1.9-.7 1.9-.7.4.9.2 1.5.1 1.7.5.5.7 1 .7 1.7 0 2.4-1.5 2.9-2.9 3.1.3.2.5.6.5 1.2v2A7 7 0 0 0 8 1Z" /></>,
  };
  return <svg width={size} height={size} viewBox="0 0 16 16" fill="none" stroke="currentColor" strokeWidth="1.4" strokeLinecap="round" strokeLinejoin="round" aria-hidden="true">{paths[name]}</svg>;
}

const commits = [
  { id: "tests", title: "Add session refresh tests", hash: "d29f50", person: "You", time: "now", lane: 1 },
  { id: "current", title: "Read sessions with the current key", hash: "5be27d", person: "Lena", time: "6m", lane: 0 },
  { id: "keys", title: "Rotate session keys", hash: "a3f9c1", person: "Lena", time: "18m", lane: 0 },
  { id: "refresh", title: "Refresh sessions near expiry", hash: "c70a92", person: "You", time: "25m", lane: 1 },
  { id: "consent", title: "Add analytics consent banner", hash: "e83c51", person: "Sam", time: "32m", lane: 2 },
  { id: "expiry", title: "Read session expiry from the token", hash: "1f8eb3", person: "You", time: "40m", lane: 1 },
  { id: "checkout", title: "Track checkout funnel events", hash: "62b0e4", person: "Sam", time: "2h", lane: 2 },
  { id: "bump", title: "Bump next to 16.3", hash: "9c2d4a", person: "Sam", time: "3h", lane: 0 },
];
const rowHeight = 32.3;
const motionEase = [.23, 1, .32, 1] as const;

function ConflictDetails({ id }: { id: string }) {
  return <div className="nmc-tooltip" role="tooltip" id={id}><h4>Lena Park <span>changed the same lines on main</span></h4>{[
    ["middleware.ts", "18", "const session = await readSession(req, keys)", "if (nearExpiry(session)) await refresh(session)"],
    ["auth.ts", "42", "return verify(token, keys.current)", "return refreshIfNear(token, 5 * MINUTE)"],
    ["auth.ts", "57", "const ttl = keys.current.ttl", "const ttl = session.expiresAt - Date.now()"],
  ].map(([file, line, theirs, yours]) => <div className="nmc-diff-file" key={file + line}><p>{file} <span>line {line}</span></p><div className="nmc-diff-code"><span>Lena</span><code>{theirs}</code></div><div className="nmc-diff-code" data-you><span>You</span><code>{yours}</code></div></div>)}</div>;
}

export function MergeConflicts({ title = "Refresh sessions in the auth middleware", prNumber = 128, repository = "acme-webapp", branch = "feat/session-refresh", pullRequestUrl = "https://github.com", speed = 1, autoplay = false, paused = false, replayKey = 0 }: MergeConflictsProps) {
  const reduced = useReducedMotion();
  const detailsId = useId();
  const [stage, setStage] = useState<Stage>(autoplay ? "idle" : "conflicts");
  const [run, setRun] = useState(0);
  const [time, setTime] = useState(0), [tooltip, setTooltip] = useState(false), [history, setHistory] = useState(false), [prompt, setPrompt] = useState("");
  const [visible, setVisible] = useState(true);
  const host = useRef<HTMLDivElement>(null), elapsed = useRef(0), command = useRef(0);
  const speedRef = useRef(speed); speedRef.current = speed;
  const reset = (next: Stage) => { setRun(value => value + 1); command.current++; elapsed.current = 0; setTime(0); setStage(next); setTooltip(false); };
  useEffect(() => { reset(autoplay ? "idle" : "conflicts"); }, [replayKey, autoplay]);
  useEffect(() => {
    let onScreen = true;
    const sync = () => setVisible(onScreen && !document.hidden);
    const observer = new IntersectionObserver(([entry]) => { onScreen = entry.isIntersecting; sync(); });
    observer.observe(host.current!);document.addEventListener("visibilitychange", sync);
    return () => { observer.disconnect(); document.removeEventListener("visibilitychange", sync); };
  }, []);
  useEffect(() => {
    const active = stage === "idle" || stage === "creating" || stage === "resolving" || stage === "merging" || (autoplay && (stage === "conflicts" || stage === "ready"));
    if (!active || paused || !visible) return;
    let raf = 0, previous = 0, stopped = false; const generation = command.current;
    const limits: Partial<Record<Stage, number>> = { idle: 2000, creating: 5000, conflicts: 5800, resolving: 6600, ready: 5600, merging: 1100 };
    const next: Partial<Record<Stage, Stage>> = { idle: "creating", creating: "conflicts", conflicts: "resolving", resolving: "ready", ready: "merging", merging: "merged" };
    const tick = (now: number) => {
      if (stopped || generation !== command.current) return;
      if (previous) elapsed.current += Math.max(0, now - previous) * Math.max(.25, Math.min(3, Number.isFinite(speedRef.current) ? speedRef.current : 1));
      previous = now;
      setTime(elapsed.current);
      if (elapsed.current >= limits[stage]!) { elapsed.current = 0; setTime(0); setStage(next[stage]!); return; }
      raf = requestAnimationFrame(tick);
    };
    raf = requestAnimationFrame(tick);
    return () => { stopped = true; cancelAnimationFrame(raf); };
  }, [stage, autoplay, paused, visible, run]);
  const resolving = stage === "resolving", ready = stage === "ready", merging = stage === "merging", merged = stage === "merged", creating = stage === "creating";
  const inserted = ready || merging || merged || (resolving && time >= 900);
  const fixed = ready || merging || merged ? 3 : resolving ? Math.min(3, Math.floor(Math.max(0, time - 1300) / 1000)) : 0;
  const remaining = 3 - fixed, testing = resolving && time >= 4400;
  const tests = testing ? Math.min(42, Math.max(1, Math.floor((time - 4400) / 2200 * 42))) : ready || merging || merged ? 42 : 0;
  const showChecks = ready || merging;
  const topMerge = !creating || time >= 3200;
  const rowCount = (topMerge ? 9 : 6) + (inserted ? 1 : 0);
  const y = (row: number) => row * rowHeight + 16;
  const position = (index: number) => topMerge ? index + 1 + (inserted ? 1 : 0) : index >= 3 ? index - 2 : index;
  const blue = merged ? "#9652e7" : "#4c91e8", green = "#20c7a4", grey = "var(--nmc-graph-muted)", amber = "#e8ac1d";
  const transition = reduced ? { duration: 0 } : { duration: .36, ease: motionEase };
  const summary = merged ? "Merged" : ready ? "Ready to merge" : resolving || merging ? "Resolving" : creating ? "Creating PR" : "3 conflicts";
  let status = "3 conflicts with main";
  if (creating) status = time < 1400 ? "Checking for local changes" : time < 3200 ? "Pushing 3 commits to origin" : "Checking if it merges cleanly";
  else if (resolving) status = time < 1300 ? "Merging main into the branch" : testing ? tests === 42 ? "Running lint and type checks" : `Running ${tests} of 42 tests` : `Resolving conflict ${Math.min(3, fixed + 1)} of 3`;
  else if (ready) status = "Ready to merge";
  else if (merging) status = "Merging into main";
  else if (merged) status = "Merged into main";
