      {history && <p className="nmc-history">Inspected changes · Created branch · Pushed 3 commits</p>}
      {cardVisible && <motion.div className="nmc-panel" initial={reduced ? false : { opacity: 0, transform: "translateY(7px)" }} animate={{ opacity: 1, transform: "translateY(0px)" }} transition={transition}>
        <div className="nmc-panel-head"><h3>{title} <span>{!creating || time >= 3000 ? `#${prNumber}` : ""}</span></h3>{(!creating || time >= 3000) && <span className="nmc-pr-state"><i className="nmc-dot" />{merged ? "Merged" : "Open"}</span>}</div>
        <motion.div className="nmc-graph-area" initial={false} animate={{ height: (creating ? createRows : rowCount) * rowHeight }} transition={transition}>
          <svg className="nmc-graph" preserveAspectRatio="none" viewBox={`0 0 57 ${rowCount * rowHeight}`} style={{ height: rowCount * rowHeight, clipPath: creating ? `inset(0 0 ${(rowCount - createRows) * rowHeight}px 0)` : undefined }} aria-hidden="true">
            <motion.path fill="none" stroke="var(--nmc-line)" strokeWidth="1.5" strokeDasharray="9 5" animate={{ d: `M12 ${y(0)}V${y(rowCount - 1) + 28}` }} transition={transition} />
            <motion.path fill="none" stroke={blue} strokeOpacity=".45" strokeWidth="1.5" animate={{ d: `M30 ${y(topMerge ? 1 : 0)}V${y(position(5))}C30 ${y(position(5)) + 30} 12 ${y(position(7)) - 21} 12 ${y(position(7))}` }} transition={transition} />
            <motion.path fill="none" stroke={green} strokeOpacity=".4" strokeWidth="1.5" animate={{ d: `M48 ${y(position(4))}V${y(position(6))}C48 ${y(position(6)) + 14} 12 ${y(position(7)) - 9} 12 ${y(position(7))}` }} transition={transition} />
            {topMerge && <><path d={`M12 ${y(0)}C12 29 30 29 30 ${y(1)}`} stroke={merged ? blue : ready ? "#48c875" : amber} strokeWidth="1.6" strokeDasharray={merged ? undefined : "4 4"} fill="none" opacity=".8" />
            <circle cx="12" cy={y(0)} r="10" fill={`color-mix(in srgb, ${merged ? "#9652e7" : ready ? "#34cf72" : "#e8ac1d"} 12%, var(--nmc-surface))`} />
            <circle cx="12" cy={y(0)} r="6.5" fill={merged ? blue : ready ? "#34cf72" : amber} />
            {ready || merged ? <path d="m9 16 2 2 4-4" stroke="#fff" strokeWidth="1.3" fill="none" /> : <path d="M12 12v5m0 2v.2" stroke="#fff" strokeWidth="1.6" strokeLinecap="round" />}</>}
            {inserted && <motion.circle initial={false} cx="30" cy={y(1)} r="5" fill={merged ? blue : "var(--nmc-surface)"} stroke={blue} strokeWidth="1.7" />}
