            {commits.map((commit, index) => <motion.circle key={commit.id} cx={[12, 30, 48][commit.lane]} animate={{ cy: y(position(index)), fill: commit.lane === 2 ? green : commit.lane === 1 ? blue : !creating && ((index === 1 && fixed < 1) || (index === 2 && fixed < 3)) ? amber : grey, opacity: !topMerge && (index === 1 || index === 2) ? 0 : 1 }} transition={transition} r="4.5" stroke="var(--nmc-surface)" strokeWidth="1.4" />)}
