              <span className="nmc-row-title">{commit.title}</span>{index === 0 && !inserted && <span className="nmc-branch">{branch}</span>}{index === 4 && <span className="nmc-branch" data-green>feat/checkout-analytics</span>}{index === 1 && !merged && <span className="nmc-main">main</span>}{conflict && <span className="nmc-conflict-count">{index === 1 ? 1 : Math.max(1, 2 - Math.max(0, fixed - 1))}</span>}{check && <span className="nmc-fixed"><Icon name="check" size={12} /></span>}<span className="nmc-row-meta"><span className="nmc-hash">{commit.hash}</span>{commit.person} · {commit.time}</span>
